static inline uint8_t xt(uint8_t a){return (a&0x80)?((a<<1)^0x1b)&0xff:(a<<1);} static inline void mix(uint8_t a[4]){uint8_t t=a[0]^a[1]^a[2]^a[3],u=a[0];a[0]^=t^xt(a[0]^a[1]);a[1]^=t^xt(a[1]^a[2]);a[2]^=t^xt(a[2]^a[3]);a[3]^=t^xt(a[3]^u);} static inline void shift(uint8_t s[4][4]){uint8_t t,u;t=s[0][1];s[0][1]=s[1][1];s[1][1]=s[2][1];s[2][1]=s[3][1];s[3][1]=t;t=s[0][2];u=s[1][2];s[0][2]=s[2][2];s[1][2]=s[3][2];s[2][2]=t;s[3][2]=u;t=s[3][3];s[3][3]=s[2][3];s[2][3]=s[1][3];s[1][3]=s[0][3];s[0][3]=t;}
void enc_nosb(const uint8_t key[16], uint8_t out[16]){uint8_t w[44][4];memcpy(w,key,16);for(int i=4;i<44;i++){if((i&3)==0){w[i][0]=w[i-4][0]^S[w[i-1][1]]^Rcon[i/4];w[i][1]=w[i-4][1]^S[w[i-1][2]];w[i][2]=w[i-4][2]^S[w[i-1][3]];w[i][3]=w[i-4][3]^S[w[i-1][0]];}else for(int j=0;j<4;j++)w[i][j]=w[i-4][j]^w[i-1][j];}uint8_t s[4][4]={{0}};for(int i=0;i<4;i++)for(int j=0;j<4;j++)s[i][j]^=w[i][j];for(int r=1;r<10;r++){shift(s);for(int i=0;i<4;i++)mix(s[i]);for(int i=0;i<4;i++)for(int j=0;j<4;j++)s[i][j]^=w[4*r+i][j];}shift(s);for(int i=0;i<4;i++)for(int j=0;j<4;j++)s[i][j]^=w[40+i][j];for(int i=0;i<4;i++)for(int j=0;j<4;j++)out[4*i+j]=s[i][j];}
int hv(char c){if(c>='0'&&c<='9')return c-'0'; if(c>='a'&&c<='f')return c-'a'+10; if(c>='A'&&c<='F')return c-'A'+10; return 0;} void parse(const char*h,uint8_t*b,int n){for(int i=0;i<n;i++)b[i]=(hv(h[2*i])<<4)|hv(h[2*i+1]);}
int main(int argc,char**argv){if(argc<6){fprintf(stderr,"usage key8hex w3hex cthex maskhex knownw2hex\n");return 1;}uint8_t base[16]={0},ct[16],known[4];parse(argv[1],base,8);parse(argv[2],base+12,4);parse(argv[3],ct,16);unsigned mask=0;sscanf(argv[4],"%x",&mask);parse(argv[5],known,4);int pos[4],m=0;for(int i=0;i<4;i++){if(mask&(1<<i))base[8+i]=known[i];else pos[m++]=i;}uint64_t total=1ULL<<(8*m);volatile int found=0;double t=omp_get_wtime();
#pragma omp parallel for schedule(static)
for(uint64_t idx=0;idx<total;idx++){if(found)continue;uint8_t k[16];memcpy(k,base,16);uint64_t z=idx;for(int a=0;a<m;a++){k[8+pos[a]]=z&0xff;z>>=8;}uint8_t out[16];enc_nosb(k,out);if(out[0]==ct[0]&&out[1]==ct[1]&&out[2]==ct[2]&&out[3]==ct[3]&&memcmp(out,ct,16)==0){found=1;printf("%02x%02x%02x%02x\n",k[8],k[9],k[10],k[11]);fflush(stdout);}}
fprintf(stderr,"searched %llu in %.3fs\n",(unsigned long long)total,omp_get_wtime()-t);return found?0:2;}
